"""Quest engine. Do not edit this file.

Run `python quest.py --help` to see how to use it.
"""
import argparse
import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
STAGES_FILE = HERE / "stages.json"
PROGRESS_FILE = HERE / ".progress.json"


def normalize(answer):
    return " ".join(answer.strip().lower().split())


def sha256(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def load_stages():
    return json.loads(STAGES_FILE.read_text(encoding="utf-8"))


def load_progress():
    try:
        return json.loads(PROGRESS_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def save_progress(progress):
    PROGRESS_FILE.write_text(json.dumps(progress, indent=2), encoding="utf-8")


def make_flag(github_id, answers):
    joined = "|".join(normalize(a) for a in answers)
    return "FLAG{" + sha256(github_id.strip().lower() + "|" + joined)[:10] + "}"


def ask_github_id(progress):
    """Ask for the GitHub ID once and remember it."""
    if progress.get("github_id"):
        return progress["github_id"]
    print()
    print("Your flag is made for your GitHub account.")
    while True:
        github_id = input("Type your GitHub ID (the name in https://github.com/<ID>): ").strip().lstrip("@")
        if github_id and " " not in github_id:
            break
        print("A GitHub ID has no spaces. Try again.")
    progress["github_id"] = github_id
    save_progress(progress)
    return github_id


def show_flag(quest, progress):
    stages = quest["stages"]
    github_id = ask_github_id(progress)
    flag = make_flag(github_id, [progress[str(i)] for i in range(1, len(stages) + 1)])
    print()
    print(f"Here is your flag, {github_id}:")
    print()
    print(f"    {flag}")
    print()
    print("Submit it with the 'Submit a Flag' form in Guild HQ:")
    print(f"    {quest.get('submit_url', '(ask the guild master)')}")
    print("(If your GitHub ID was wrong, run: python quest.py --id)")


def show_status(quest, progress):
    print(quest["title"])
    for i, _ in enumerate(quest["stages"], start=1):
        mark = "cleared" if str(i) in progress else "not cleared"
        print(f"  Stage {i}: {mark}")


def play_stage(quest, progress, number):
    stages = quest["stages"]
    if not 1 <= number <= len(stages):
        print(f"Error: there is no stage {number}. This quest has {len(stages)} stages.")
        return 1
    for previous in range(1, number):
        if str(previous) not in progress:
            print(f"Error: clear stage {previous} first.")
            return 1

    stage = stages[number - 1]
    required = stage.get("requires_file")
    if required and not (HERE / required["path"]).exists():
        print("Traceback (most recent call last):")
        print(f'  File "quest.py", line {40 + number}, in <module>')
        print(required["error"])
        return 1

    print(f"== Stage {number} ==")
    print(stage["question"])
    answer = input("Your answer: ")
    if sha256(normalize(answer)) != stage["answer_sha256"]:
        print("That is not right. Read the README again.")
        return 1

    progress[str(number)] = normalize(answer)
    save_progress(progress)
    print(f"Correct! Stage {number} cleared.")

    if all(str(i) in progress for i in range(1, len(stages) + 1)):
        print()
        print("You cleared every stage!")
        show_flag(quest, progress)
    else:
        print(f"Next: python quest.py --stage {number + 1}")
    return 0


def main():
    quest = load_stages()
    parser = argparse.ArgumentParser(
        description=f"{quest['title']} - answer every stage to get the flag.",
        epilog="Example: python quest.py --stage 1",
    )
    parser.add_argument("--stage", type=int, metavar="N", help="play stage N")
    parser.add_argument("--status", action="store_true", help="show which stages you have cleared")
    parser.add_argument("--flag", action="store_true", help="show your flag again")
    parser.add_argument("--id", action="store_true", help="change your GitHub ID and show your flag again")
    parser.add_argument("--reset", action="store_true", help="forget your progress and start again")
    args = parser.parse_args()

    progress = load_progress()
    if args.flag or args.id:
        if args.id:
            progress.pop("github_id", None)
        if not all(str(i) in progress for i in range(1, len(quest["stages"]) + 1)):
            print("You have not cleared every stage yet. Run: python quest.py --status")
            return 1
        show_flag(quest, progress)
        return 0
    if args.reset:
        if PROGRESS_FILE.exists():
            PROGRESS_FILE.unlink()
        print("Your progress has been reset.")
        return 0
    if args.status:
        show_status(quest, progress)
        return 0
    if args.stage is None:
        parser.print_help()
        return 0
    return play_stage(quest, progress, args.stage)


if __name__ == "__main__":
    sys.exit(main())
